-- Size: Issued Amount Weight
koscom_mdcsrealtime_securitiesb_exture_v2_018.issued_amount_weight.size = 16

-- Display: Issued Amount Weight
koscom_mdcsrealtime_securitiesb_exture_v2_018.issued_amount_weight.display = function(value, buffer, offset, packet, parent)
  local raw = buffer(offset, koscom_mdcsrealtime_securitiesb_exture_v2_018.issued_amount_weight.size):string()
  local text = format_decimal_text(raw)

  if text == nil then
    return "Issued Amount Weight: No Value"
  end

  local point = text:find(".", 1, true)
  local places = point and (#text - point) or 0

  if places ~= 6 then
    return "Issued Amount Weight: "..text.." (expected 6 places)"
  end

  return "Issued Amount Weight: "..text
end

