-- Listed Amount
koscom_mdcsrealtime_securitiesb_exture_v2_018.listed_amount = {}

-- Size: Listed Amount
koscom_mdcsrealtime_securitiesb_exture_v2_018.listed_amount.size = 22

-- Display: Listed Amount
koscom_mdcsrealtime_securitiesb_exture_v2_018.listed_amount.display = function(value, buffer, offset, packet, parent)
  local raw = buffer(offset, koscom_mdcsrealtime_securitiesb_exture_v2_018.listed_amount.size):string()
  local text = format_decimal_text(raw)

  if text == nil then
    return "Listed Amount: No Value"
  end

  local point = text:find(".", 1, true)
  local places = point and (#text - point) or 0

  if places ~= 3 then
    return "Listed Amount: "..text.." (expected 3 places)"
  end

  return "Listed Amount: "..text
end

-- Dissect: Listed Amount
koscom_mdcsrealtime_securitiesb_exture_v2_018.listed_amount.dissect = function(buffer, offset, packet, parent)
