koscom_mdcsrealtime_securitiesb_exture_v2_018.maximum_order_price.size = 22

-- Display: Maximum Order Price
koscom_mdcsrealtime_securitiesb_exture_v2_018.maximum_order_price.display = function(value, buffer, offset, packet, parent)
  local raw = buffer(offset, koscom_mdcsrealtime_securitiesb_exture_v2_018.maximum_order_price.size):string()
  local text = format_decimal_text(raw)

  if text == nil then
    return "Maximum Order Price: No Value"
  end

  local point = text:find(".", 1, true)
  local places = point and (#text - point) or 0

  if places ~= 3 then
    return "Maximum Order Price: "..text.." (expected 3 places)"
  end

  return "Maximum Order Price: "..text
end

-- Dissect: Maximum Order Price
koscom_mdcsrealtime_securitiesb_exture_v2_018.maximum_order_price.dissect = function(buffer, offset, packet, parent)
  local length = koscom_mdcsrealtime_securitiesb_exture_v2_018.maximum_order_price.size
  local range = buffer(offset, length)
  local value = tonumber(range:string())

  if value == nil then
    value = 0
    local item = parent:add(omi_koscom_mdcsrealtime_securitiesb_exture_v2_018.fields.maximum_order_price, range, value, "Maximum Order Price: Not Applicable")
    item:add_proto_expert_info(koscom_mdcsrealtime_securitiesb_exture_v2_018.experts.not_a_number, "Maximum Order Price is not a number: '"..range:string().."'")
    return offset + length, value
  end

  local display = koscom_mdcsrealtime_securitiesb_exture_v2_018.maximum_order_price.display(value, buffer, offset, packet, parent)

  parent:add(omi_koscom_mdcsrealtime_securitiesb_exture_v2_018.fields.maximum_order_price, range, value, display)

  return offset + length, value
end

