-- Display: Sell Side Arbitrage Value
koscom_mdcsrealtime_securitiesb_exture_v2_018.sell_side_arbitrage_value.display = function(value, buffer, offset, packet, parent)
  local raw = buffer(offset, koscom_mdcsrealtime_securitiesb_exture_v2_018.sell_side_arbitrage_value.size):string()
  local text = format_decimal_text(raw)

  if text == nil then
    return "Sell Side Arbitrage Value: No Value"
  end

  local point = text:find(".", 1, true)
  local places = point and (#text - point) or 0

  if places ~= 3 then
    return "Sell Side Arbitrage Value: "..text.." (expected 3 places)"
  end

  return "Sell Side Arbitrage Value: "..text
end

