-- Display: Trading Price
koscom_mdcsrealtime_securitiesb_exture_v2_018.trading_price.display = function(value, buffer, offset, packet, parent)
  local raw = buffer(offset, koscom_mdcsrealtime_securitiesb_exture_v2_018.trading_price.size):string()
  local text = format_decimal_text(raw)

  if text == nil then
    return "Trading Price: No Value"
  end

  return "Trading Price: "..text
end

-- Dissect: Trading Price
koscom_mdcsrealtime_securitiesb_exture_v2_018.trading_price.dissect = function(buffer, offset, packet, parent)
  local length = koscom_mdcsrealtime_securitiesb_exture_v2_018.trading_price.size
  local range = buffer(offset, length)
  local value = tonumber(range:string())

  if value == nil then
    value = 0
    local item = parent:add(omi_koscom_mdcsrealtime_securitiesb_exture_v2_018.fields.trading_price, range, value, "Trading Price: Not Applicable")
    item:add_proto_expert_info(koscom_mdcsrealtime_securitiesb_exture_v2_018.experts.not_a_number, "Trading Price is not a number: '"..range:string().."'")
    return offset + length, value
  end

  local display = koscom_mdcsrealtime_securitiesb_exture_v2_018.trading_price.display(value, buffer, offset, packet, parent)

  parent:add(omi_koscom_mdcsrealtime_securitiesb_exture_v2_018.fields.trading_price, range, value, display)

  return offset + length, value
end

